import { afterEach, describe, expect, it } from "vitest";
import {
  assertFetchableScheme,
  assertNoSecretInUrl,
  assertNoUserinfo,
  classifyFetchTarget,
  isUnresolvedInternalName,
  secretKindsInUrl,
  urlReviewReason,
} from "./fetchUrlSafety";
import { setHostResolver } from "./networkAddress";
import { secretCases } from "./secretScan/fixtures";

afterEach(() => setHostResolver(undefined));

// Generated by the secret scanner's own fixtures, so no secret-shaped literal sits in the source
const pat = () => secretCases().find((c) => c.ruleId === "github-pat")!.value;

describe("scheme and userinfo (T10, T11)", () => {
  it.each([
    "file:///etc/passwd",
    "data:text/html,x",
    "javascript:alert(1)",
    "ftp://host/",
    "gopher://host/",
  ])("refuses %s", (u) => {
    expect(() => assertFetchableScheme(new URL(u))).toThrow(
      /only http and https/,
    );
  });

  it("allows http and https", () => {
    assertFetchableScheme(new URL("http://a.test/"));
    assertFetchableScheme(new URL("https://a.test/"));
  });

  it("refuses credentials in the URL", () => {
    expect(() =>
      assertNoUserinfo(new URL("https://user:pass@example.com/")),
    ).toThrow(/user name or password/);
    expect(() =>
      assertNoUserinfo(new URL("https://user@example.com/")),
    ).toThrow();
    assertNoUserinfo(new URL("https://example.com/"));
  });

  it("host is evil.example for https://evil.example/#@127.0.0.1/ (T15)", () => {
    const u = new URL("https://evil.example/#@127.0.0.1/");
    expect(u.hostname).toBe("evil.example");
    assertNoUserinfo(u);
  });
});

describe("secret in the URL (T12)", () => {
  it("refuses a provider key in the query, naming the kind and not the value", () => {
    const key = pat();
    const url = new URL(`https://example.com/?k=${key}`);
    expect(secretKindsInUrl(url).length).toBeGreaterThan(0);
    let message = "";
    try {
      assertNoSecretInUrl(url);
    } catch (e) {
      message = (e as Error).message;
    }
    expect(message).toMatch(/credential/);
    expect(message).not.toContain(key);
  });

  it("finds one in the path and one that is percent-encoded", () => {
    const key = pat();
    expect(() =>
      assertNoSecretInUrl(new URL(`https://e.test/${key}/x`)),
    ).toThrow();
    const enc = encodeURIComponent(`key=${key}`);
    expect(() =>
      assertNoSecretInUrl(new URL(`https://e.test/?q=${enc}`)),
    ).toThrow();
  });

  it("finds a secret from the environment by exact value", () => {
    const value = "correct-horse-battery-staple-9271";
    const url = new URL(`https://e.test/?q=${value}`);
    expect(
      secretKindsInUrl(url, { MY_SERVICE_API_KEY: value }).length,
    ).toBeGreaterThan(0);
    expect(secretKindsInUrl(url, {})).toEqual([]);
  });

  it("passes ordinary URLs", () => {
    for (const u of [
      "https://example.com/",
      "https://en.wikipedia.org/wiki/Zero-width_space?action=raw",
      "https://github.com/a/b/commit/0123456789abcdef0123456789abcdef01234567",
      "https://example.com/search?q=how+to+parse+json+in+typescript",
    ]) {
      expect(secretKindsInUrl(new URL(u), {})).toEqual([]);
      expect(urlReviewReason(u)).toBeUndefined();
    }
  });
});

describe("urlReviewReason (T13)", () => {
  it("asks about a long base64 query that is not a secret shape", () => {
    const blob = Buffer.from(
      Array.from({ length: 220 }, (_, i) => (i * 37 + (i % 7) * 91) % 256),
    ).toString("base64");
    expect(blob.length).toBeGreaterThan(250);
    expect(urlReviewReason(`https://evil.example/c?d=${blob}`)).toMatch(
      /encoded/,
    );
  });

  it("asks about userinfo and about secrets; ignores non-URLs", () => {
    expect(urlReviewReason("https://u:p@example.com/")).toMatch(/credentials/);
    expect(urlReviewReason(`https://e.test/?k=${pat()}`)).toMatch(/credential/);
    expect(urlReviewReason("not a url")).toBeUndefined();
    expect(urlReviewReason(undefined)).toBeUndefined();
  });

  it("does not ask about a long English slug", () => {
    expect(
      urlReviewReason(
        "https://blog.example/2026/11/why-we-moved-our-build-system-from-make-to-bazel-and-what-we-learned-along-the-way-part-two",
      ),
    ).toBeUndefined();
  });
});

describe("unresolved internal names behind a proxy (T26)", () => {
  it("flags a name that resolves to nothing and has no real TLD", () => {
    for (const h of ["jenkins", "intranet", "git.corp", "nas.lan"]) {
      expect(isUnresolvedInternalName(h, [])).toBe(true);
    }
  });

  it("does not flag a name under a real TLD, a resolved name, or an address", () => {
    expect(isUnresolvedInternalName("example.com", [])).toBe(false);
    expect(isUnresolvedInternalName("docs.example.co.uk", [])).toBe(false);
    expect(isUnresolvedInternalName("example.xn--p1ai", [])).toBe(false);
    expect(isUnresolvedInternalName("jenkins", ["93.184.215.14"])).toBe(false);
    expect(isUnresolvedInternalName("93.184.215.14", [])).toBe(false);
    expect(isUnresolvedInternalName("[2001:db8::1]", [])).toBe(false);
  });

  it("classifyFetchTarget asks for the internal name and not for a public one", async () => {
    setHostResolver(async (host) => {
      if (host === "example.com") return ["93.184.215.14"];
      throw new Error("ENOTFOUND");
    });
    expect((await classifyFetchTarget("example.com")).nonPublic).toBe(false);
    expect((await classifyFetchTarget("wiki.corp")).nonPublic).toBe(true);
    // a real TLD that does not resolve here: left to the transport
    expect((await classifyFetchTarget("gone.example.org")).nonPublic).toBe(
      false,
    );
  });
});
